  3149  /*
  3150   * Used by cram_ref_load and cram_ref_get. The file handle will have
  3151   * already been opened, so we can catch it. The ref_entry *e informs us
  3152   * of whether this is a multi-line fasta file or a raw MD5 style file.
  3153   * Either way we create a single contiguous sequence.
  3154   *
  3155   * Returns all or part of a reference sequence on success (malloced);
  3156   *         NULL on failure.
  3157   */
  3158  static char *load_ref_portion(BGZF *fp, ref_entry *e, int start, int end) {
  3159      off_t offset, len;
  3160      char *seq;
  3161
  3162      if (end < start)
  3163          end = start;
  3164
  3165      /*
  3166       * Compute locations in file. This is trivial for the MD5 files, but
  3167       * is still necessary for the fasta variants.
  3168       */
  3169      offset = e->line_length
  3170          ? e->offset + (start-1)/e->bases_per_line * e->line_length +
  3171            (start-1) % e->bases_per_line
  3172          : start-1;
  3173
  3174      len = (e->line_length
  3175             ? e->offset + (end-1)/e->bases_per_line * e->line_length +
  3176               (end-1) % e->bases_per_line
  3177             : end-1) - offset + 1;
  3178
  3179      if (bgzf_useek(fp, offset, SEEK_SET) < 0) {
  3180          perror("bgzf_useek() on reference file");
  3181          return NULL;
  3182      }
  3183
  3184      if (len == 0 || !(seq = malloc(len))) {
  3185          return NULL;
  3186      }
  3187
  3188      if (len != bgzf_read(fp, seq, len)) {
  3189          perror("bgzf_read() on reference file");
  3190          free(seq);
  3191          return NULL;
  3192      }
  3193
  3194      /* Strip white-space if required. */
  3195      if (len != end-start+1) {
  3196          int i, j;
  3197          char *cp = seq;
  3198          char *cp_to;
  3199
  3200          for (i = j = 0; i < len; i++) {
  3201              if (cp[i] >= '!' && cp[i] <= '~')
  3202                  cp[j++] = toupper_c(cp[i]);
  3203          }
  3204          cp_to = cp+j;
  3205
  3206          if (cp_to - seq != end-start+1) {
  3207              hts_log_error("Malformed reference file");
  3208              free(seq);
  3209              return NULL;
  3210          }
  3211      } else {
  3212          int i;
  3213          for (i = 0; i < len; i++) {
  3214              seq[i] = toupper_c(seq[i]);
  3215          }
  3216      }
  3217
  3218      return seq;
