    62  /*
    63   * Decodes the Tag Dictionary record in the preservation map
    64   * Updates the cram compression header.
    65   *
    66   * Returns number of bytes decoded on success
    67   *        -1 on failure
    68   */
    69  int cram_decode_TD(cram_fd *fd, char *cp, const char *endp,
    70                     cram_block_compression_hdr *h) {
    71      char *op = cp;
    72      unsigned char *dat;
    73      cram_block *b;
    74      int32_t blk_size = 0;
    75      int nTL, i, sz, err = 0;
    76
    77      if (!(b = cram_new_block(0, 0)))
    78          return -1;
    79
    80      if (h->TD_blk || h->TL) {
    81          hts_log_warning("More than one TD block found in compression header");
    82          cram_free_block(h->TD_blk);
    83          free(h->TL);
    84          h->TD_blk = NULL;
    85          h->TL = NULL;
    86      }
    87
    88      /* Decode */
    89      blk_size = fd->vv.varint_get32(&cp, endp, &err);
    90      if (!blk_size) {
    91          h->nTL = 0;
    92          cram_free_block(b);
    93          return cp - op;
    94      }
    95
    96      if (err || blk_size < 0 || endp - cp < blk_size) {
    97          cram_free_block(b);
    98          return -1;
    99      }
   100
   101      BLOCK_APPEND(b, cp, blk_size);
   102      cp += blk_size;
   103      sz = cp - op;
   104      // Force nul termination if missing
   105      if (BLOCK_DATA(b)[BLOCK_SIZE(b)-1])
   106          BLOCK_APPEND_CHAR(b, '\0');
   107
   108      /* Set up TL lookup table */
   109      dat = BLOCK_DATA(b);
   110
   111      // Count
   112      for (nTL = i = 0; i < BLOCK_SIZE(b); i++) {
   113          nTL++;
   114          while (dat[i])
   115              i++;
   116      }
   117
   118      // Copy
   119      if (!(h->TL = calloc(nTL, sizeof(*h->TL)))) {
   120          cram_free_block(b);
   121          return -1;
   122      }
   123      for (nTL = i = 0; i < BLOCK_SIZE(b); i++) {
   124          h->TL[nTL++] = &dat[i];
   125          while (dat[i])
   126              i++;
   127      }
   128      h->TD_blk = b;
   129      h->nTL = nTL;
   130
   131      return sz;
   132
   133   block_err:
   134      cram_free_block(b);
   135      return -1;
   136  }
